import sys
import requests
import json
from datetime import datetime

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    currency_code = sys.argv[1]
    url = f"https://api.frankfurter.app/latest?from=USD&to={currency_code}"

    try:
        response = requests.get(url)
        response.raise_for_status()
        data = response.json()

        if not isinstance(data.get("rates"), dict) or currency_code not in data["rates"]:
            sys.exit(1)

        rate = float(data["rates"][currency_code])
        date = data["date"]

        print(f"{rate:.6f}")
        with open("rate.cache", "w", encoding="utf-8") as f:
            f.write(f"{date} {rate:.6f}")

    except (requests.exceptions.RequestException, ValueError):
        try:
            with open("rate.cache", "r", encoding="utf-8") as f:
                cached_line = f.read().strip()
                if cached_line:
                    date, cached_rate = cached_line.split()
                    try:
                        cached_rate = float(cached_rate)
                        print(f"{cached_rate:.6f}")
                        timestamp = datetime.now().strftime("%Y-%m-%dT%H:%M:%S")
                        print(f"{timestamp} WARNING {currency_code}: connection error, using cached rate")
                    except ValueError:
                        sys.exit(1)
                else:
                    sys.exit(1)
        except FileNotFoundError:
            sys.exit(1)

    except Exception as e:
        timestamp = datetime.now().strftime("%Y-%m-%dT%H:%M:%S")
        print(f"{timestamp} ERROR {currency_code}: unexpected error")
        sys.exit(1)

if __name__ == "__main__":
    main()
